import sys
from collections import OrderedDict


def main():
    lines = sys.stdin.read().splitlines()
    capacity = int(lines[0])
    cache = OrderedDict()

    for line in lines[1:]:
        parts = line.split()
        if not parts:
            continue

        if parts[0] == "put":
            if len(cache) >= capacity:
                evict_key = next(iter(cache))
                del cache[evict_key]
                print("evict", evict_key)
            cache[parts[1]] = parts[2]
        elif parts[0] == "get":
            print(cache.get(parts[1], "miss"))
        elif parts[0] == "dump":
            if not cache:
                print("empty")
            else:
                print(" ".join(cache.keys()))


if __name__ == "__main__":
    main()
